      const rm = /^re-([a-z]+)$/.exec(w);
      if (rm && !known({ w: w, k: 'w' }) && cand({ w: rm[1], k: 'w' }, '動', ['base', '3sg', 'past', 'pp', 'ing'])) {
        push(s, rm[1], 'w'); out[out.length - 1].re = true; return;
      }
      // five-minute / ten-year-old / twenty-five-meter: 数の語 + 単位のハイフンつなぎは語に分ける（名詞句で「5分の」「10歳の」と読む）
      const hOld = /-old$/.test(w), hm = /^([a-z]+(?:-[a-z]+)?)-([a-z]+)$/.exec(hOld ? w.slice(0, -4) : w);
