    const SURF = { newyearsday: "New Year's Day", newyearseve: "New Year's Eve", rightnowadv: 'right now', firstcomeadv: 'on a first-come, first-served basis', bluemoonadv: 'once in a blue moon', wideadv: 'wide', wwtwo: 'World War II', wwone: 'World War I', overthere: 'over there', insideout: 'inside out', upsidedown: 'upside down', infotech: 'IT', parttimeadv: 'part-time', fulltimeadv: 'full-time' };
    out.forEach((t) => { if (t.k === 'w' && SURF[t.w]) t.s = SURF[t.w]; });
