        const pastIt = T[wh.end + 1].w === 'was' && !WH_MAINPAST;   // I didn't know how difficult it was to … → どれほど難しいか（主節が過去なら現在で訳す）
        const aIt = wh.ja.replace(/^どのくらい/, 'どれほど');
