    { const mu = measureAt(k, lim, adjC(T[k + 2]) ? adjC(T[k + 2]).lemma : ''); if (mu && mu.end < lim && (isW(T[mu.end], 'more') || isW(T[mu.end], 'less') || (adjC(T[mu.end]) && adjC(T[mu.end]).form === 'comp'))) { deg += mu.ja; k = mu.end; } }
    for (let av0 = advBeforeAdj(k, lim); av0 && k < lim - 1; av0 = advBeforeAdj(k, lim)) { deg += av0; k++; }
