        return done(vg, vbFi ? P(vpJoin(vFi, 'dict') + 'のに' + vbFi) : P(vpJoin(vFi, 'dict') + 'のを' + gFi.adv + '感じる', 'v1'), st, lim, 'SVC', o, [], { noStative: true });
