      if (nCo && isW(T[nCo.end], 'open')) { name('svoc'); return done(vg, P('割る', 'v5'), st, tail(nCo.end + 1, lim, st, o, vg), 'SVOC', o, [objStr(nCo, 'を', st)], { noStative: true }); }
