      if (/^(?:eye|eyes|mouth|lips)$/.test(ob.head || '') && /^(?:closed|shut)$/.test(tj.w)) { name('svoc'); return done(vg, P('閉じたままにする', 'suru'), st, tail(j + 1, lim, st, o, vg), 'SVOC', o, [objStr(ob, 'を', st)], { noStative: true }); }   // kept his eyes closed → 目を閉じたままにした
