        vg.neg = false; st.neg = false; vg.advs = (vg.advs || []).filter((x) => x.w !== 'only'); st.manner = st.manner.filter((x) => !/^(?:だけ|ただ|単に)$/.test(x)); st.other = st.other.filter((x) => !/^(?:だけ|ただ|単に)$/.test(x));
