    if (isW(T[a], 'there') && isW(T[a + 1], 'goes') && a + 2 < b) { const nTg = np(a + 2, b, {}); if (nTg && nTg.end === b) { name('idiom'); return { out: () => nTg.ja.replace(/^私の/, '') + 'がなくなった', sp: 'SV' }; } fail(m); }
    if (seq(a, ['here', 'we', 'are']) && (a + 3 === b || (seq(a + 3, ['at', 'last']) && a + 5 === b))) { name('idiom'); return { out: () => (a + 3 === b ? 'さあ、着いた' : 'やっと着いた'), sp: 'SV' }; }
    if (isW(T[a], 'here') && T[a + 1] && /^(?:is|are)$/.test(T[a + 1].w || '') && a + 2 < b) { const nHi = np(a + 2, b, {}); if (nHi && nHi.end === b) { name('idiom'); return { out: () => 'はい、' + nHi.ja.replace(/^(?:あなたの|私の)/, '').replace(/^変化$/, 'おつり') + 'です', sp: 'SV' }; } fail(m); }
