      if (a + 6 < b && /^(?:problem|problems|something|trouble|issue|issues)$/.test((T[a + 5] || {}).w || '') && isW(T[a + 6], 'with') && /^(?:a|an|some)$/.test(T[a + 4].w || '')) {
        const nWp = np(a + 7, b, {});
        if (nWp && nWp.end === b) { name('there'); name('idiom'); return { out: () => nWp.ja + 'に問題があるようだ' + (pastS ? 'った' : ''), sp: 'SV', past: pastS }; }
        fail(mS);
      }
