      if (nS && nS.end === b) { name('there'); name('idiom'); const negS = !!nS.neg || isW(T[a + 4], 'no'); const baseS = nS.ja.replace(/^(?:何の|どんな)/, ''); return { out: () => baseS + (negS ? 'は' : 'が') + (negS ? (nS.an ? 'いない' : 'ない') : (nS.an ? 'いる' : 'ある')) + (pastS ? 'ようだった' : 'ようだ'), sp: 'SV', past: pastS }; }
