      if (n2 && !who && (isW(T[n2.end], 'and') || isW(T[n2.end], 'or'))) { const mTc = mark(); const nTc = np(k, b, { noRel: true, noPost: true }); if (nTc && isW(T[nTc.end], 'to')) n2 = nTc; else fail(mTc); }
