          name('it-to'); pick(k, a1.e);
          const rN = done(Object.assign({}, vg, { lemma: 'be' }), P(vpJoin(infN, 'neg') + 'ほうがよい', 'i'), st, b, 'SVC', o, [], { noStative: true });
