      if (vq && vq.end === b && isW(T[a + 3], 'i')) { fail(mq); }
      else if (vq && vq.end === b) { name('question'); return Fx(isW(T[a + 3], 'we') && verbal(vq.pred) ? vq.parts.join('') + vq.pred.form('stem') + 'ませんか' : vpJoin(vq, 'te') + 'はどうですか', 'SV'); }
