      let head = null;
      if (T[a].k === 'w' && WH[T[a].w]) { const mh = mark(); const w0 = whPhrase(a, x); fail(mh); if (w0 && w0.end < x) head = T.slice(a, w0.end + 1); }
      else head = [T[a]];
      const hl = head ? head[head.length - 1] : null;
